import math

def build_instance(rng):
    linear_coefficient_1 = rng.randint(-10, 10)
    constant_term_1 = rng.randint(-10, 10)
    linear_coefficient_2 = rng.randint(-10, 10)
    constant_term_2 = rng.randint(-10, 10)
    evaluation_point = rng.randint(-10, 10)
    f = linear_coefficient_1 * evaluation_point + constant_term_1
    g = linear_coefficient_2 * evaluation_point + constant_term_2
    answer = f * g
    check = linear_coefficient_1 * linear_coefficient_2 * evaluation_point ** 2 + (linear_coefficient_1 * constant_term_2 + linear_coefficient_2 * constant_term_1) * evaluation_point + constant_term_1 * constant_term_2
    parameters = {'linear_coefficient_1': linear_coefficient_1, 'constant_term_1': constant_term_1, 'linear_coefficient_2': linear_coefficient_2, 'constant_term_2': constant_term_2, 'evaluation_point': evaluation_point}
    return (parameters, answer, check)



